from __future__ import absolute_import

from taf.selenium.gnb.oam.coam.cu import pages
from taf.selenium.gnb.oam.coam.cu.pages import v25R1


class BtsStatus(v25R1.BtsStatus):
    def __init__(self, driver, version):
        if not self._instance_dict:
            super(BtsStatus, self).__init__(driver, version)
            self._instance_dict.update(
                {"CU Properties": CUPropertiesStatusStatusPageV25R2(driver, version)})


class CUPropertiesStatusStatusPageV25R2(pages.CUPropertiesStatusStatusPage):
    MENU_ROUTE_LIST = ['marker-check', 'Site Runtime View', 'Site Properties']
